@spec tracker_page_spec  src=tests/specs/tracker_page_spec.lua  loc=1602  cases=49
@exercises tuning (tuning), configManager (h.cm), commandManager (h.cmgr), midiManager (h.mm), trackerManager (h.tm)
@surface   tuning.derive, tuning.genDiamond, cm:setContext, cmgr:push, cmgr:invoke, cm:getAt, cm:set, cm:get, tuning.stepToMidi, mm:subscribe, mm:notes, tm:assignEvent, tm:byUuid, tm:flush
@harness   mk, reaper:addItem, reaper:setProjectTracks, reaper:seedMidi

# Intent
  Pin-tests for trackerPage's Page interface (bind / unbind / focusState /
  bind-from-cursor) and the retune modal's slots, defaults and dispatch.
  render / handleInput are stubs wired in step 3 and verified in REAPER, not here.

# Helpers
  @fn resetArrange()  @ 59-161
  @fn seedItems(h, takes, srcLen)  @ 177-182
      -- A bind re-keys cm's track tier off the take's own item, so a take named in
      -- fakeArrange needs one in the fake project too.
  @fn newTrackerPage(cm, ds, cmgr, chrome, gui)  @ 184-193
  @fn trackList(trackCount)  @ 195-201
  @fn mapTracker(harness, inst, trackCount)  @ 206-220
      -- A tracker bound to the take 'i0' over a track list of the given width, with
      -- i0's placement as the caller states it; inst = nil binds it into no instance.
      -- Returns the page's tv, and the harness behind it for the cmgr.

# Cases
  @case 'bind(take) drives cm:setContext via the page's own tm:bindTake'  [harness]  @ 224-232
  @case 'unbind() drives cm:setContext(nil) via the page's own tm:bindTake'  [harness]  @ 235-244
  @case 'focusState before any render returns both bits false'  [harness]  @ 247-254
  @case 'bindFromSelection binds tm to the resolved selection take, drops when the track has no slots'  [harness]  @ 260-273
  @case 'with no live instance, the new take mints a parked slot and selects it'  [harness]  @ 277-294
  @case 'deleteBoundSlot confirms, then deletes the bound slot through the arrange facade'  [harness]  @ 300-321
  @case 'take properties renames the bound take\'s slot, not that one take'  [harness]  @ 327-345
  @case 'take properties follows the bound take when the tracker sits on another slot'  [harness]  @ 352-370
  @case 'the new take places below the current instance and becomes current'  [harness]  @ 376-409
  @case 'a new take on a just-selected track parks, rather than appending on the old one'  [harness]  @ 413-437
  @case 'duplicate below appends another instance of the bound slot and makes it current'  [harness]  @ 443-473
  @case 'duplicate below refuses where the free span falls short'  [harness]  @ 477-498
  @case 'duplicate below on a slot whose only take is parked does nothing'  [harness]  @ 502-515
  @case 'the variant step rebinds the tracker to the slot stepped to and follows its placement'  [harness]  @ 521-555
  @case 'a variant step with the tracker in no instance does nothing'  [harness]  @ 559-573
  @case 'prev/next track + take drive the tv selection, not the arrange cursor'  [harness]  @ 577-600
  @case 'a track step lands on the placement overlapping the current instance most'  [harness]  @ 604-640
  @case 'with nothing overlapping, a track step lands on the placement nearest in time'  [harness]  @ 644-679
  @case 'F6 plays from the instance dived into, not the placement the bind resolved'  [harness]  @ 686-703
  @case 'a dive outranks a play head already sitting in another instance'  [harness]  @ 707-730
  @case 'the play head entering an instance makes it current; leaving one writes nothing'  [harness]  @ 734-757
  @case 'a slot change seeks from the outgoing instance, backwards for prevTake'  [harness]  @ 761-796
  @case 'the walk steps along the track's placements in start order, holding at the ends'  [harness]  @ 800-848
  @case 'a walk into another slot resets the caret; within one slot the caret holds'  [harness]  @ 852-889
  @case 'deleting the instance drops that placement and lands on the one before it'  [harness]  @ 893-927
  @case 'a slot with no live instance leaves the tracker nowhere, and F6 silent'  [harness]  @ 931-947
  @case 'the map window centres the bound column, and clamps it at both ends'  [harness]  @ 956-974
  @case 'the map window pages time, a start in the last bar opening the next page'  [harness]  @ 978-994
  @case 'with the tracker in no instance the map window pages on the edit cursor'  [harness]  @ 998-1005
  @case 'the map window carries the takes over it, the current instance marked'  [harness]  @ 1009-1020
  @case 'the pin key holds the map up as the palette default, and drops it when pressed again'  [harness]  @ 1024-1033
  @case 'a gesture raises the map, and it falls at the next command'  [harness]  @ 1037-1078
  @case 'the play row is the head\'s offset into the current instance, in rows'  [harness]  @ 1082-1109
  @case 'the play row dims where the head is sounding a sibling instance'  [harness]  @ 1113-1137
  @case 'the cut row is where the rendered span stops short of the source'  [harness]  @ 1144-1165
  @case 'the play row and the head row count from the source origin, not the start'  [harness]  @ 1171-1195
  @case 'a dive carries the arrange QN to the caret row, and the caret hands it back'  [harness]  @ 1202-1221
  @case 'a caret outside the rendered span hands back the row the span stops at'  [harness]  @ 1225-1244
  @case 'leaving the tracker puts the arrange caret where the tracker caret is'  [harness]  @ 1248-1270
  @case 'with loop to item on, a dive brackets the instance dived into'  [harness]  @ 1276-1294
  @case 'the play head entering an instance leaves the loop where it was'  [harness]  @ 1298-1316
  @case 'the toggle command brackets the current instance as it comes on'  [harness]  @ 1320-1342
  @case 'the loop-to-item verb brackets the current instance, toggle or no toggle'  [harness]  @ 1346-1370
  @case 'retune opens on the scope the selection implies and OK snaps that scope'  [harness]  @ 1376-1431
  @case 'retune opens on the facility the take carries, its dials on their figures'  [harness]  @ 1439-1468
  @case 'a refused retune offers to widen, and the offer taken solves again'  [harness]  @ 1474-1517
  @case 'empty grid shows the single no-takes message'  [harness]  @ 1523-1537
  @case 'an owned tm flush resyncs the watcher baseline; only a foreign write trips the reload'  [harness]  @ 1544-1576
  @case 'bindFromSelection re-keys cm on return from dormancy even when the take is unchanged'  [harness]  @ 1580-1600

